/**
 * Claim overrides: integration entries the product audit PROVED are not
 * available, applied at READ time on top of the synced website catalogue.
 *
 * Why an override layer and not an edit of src/tools/integrations.ts: that
 * file's catalogue block is regenerated by scripts/sync-website-mirror.mjs, so a
 * hand edit is silently undone by the next sync. Overrides win over synced
 * content, always (plan PLAN-HELLOG-0003, AC-09).
 *
 * Each override MUST cite a known-truth id (`kt`), the code evidence, the date it
 * was verified and an `expires` date. The test suite fails once `expires` has
 * passed, and /health goes `degraded`, so a stale "not available" cannot outlive
 * its review. If a feature later ships, remove the override.
 *
 * Known-truth ids refer to the HelloGrowthCRM product audit of 2026-10-24..28:
 *   KT-18  payment gateways: Cashfree 501, PayU/Paytm no handler, the
 *          payment-link dialog offers Razorpay and Stripe only
 *   KT-19  integration cards: 194 of 360 live-listed cards have working code;
 *          21 are broken (card calls functions that are not deployed)
 *   KT-20  TallyPrime has no sync; only Tally.so form submissions create leads
 */

export interface ClaimOverride {
  slug: string;
  kt: string;
  reason: string;
  evidence: string;
  /** Date the claim was verified against code (YYYY-MM-DD). */
  as_of: string;
  /** Review-by date (YYYY-MM-DD). CI fails and /health degrades after it. */
  expires: string;
}

