export const OVERRIDE_STATUS = "not_available" as const;

const BY_SLUG = new Map(INTEGRATION_OVERRIDES.map((o) => [o.slug, o] as const));

export function getIntegrationOverride(slug: string): ClaimOverride | undefined {
  return BY_SLUG.get(slug);
}

/** Overrides whose review-by date has passed (`today` is injectable for tests). */
export function expiredOverrides(today: Date = new Date()): ClaimOverride[] {
  const iso = today.toISOString().slice(0, 10);
  return INTEGRATION_OVERRIDES.filter((o) => o.expires < iso);
}

export function overrideSummary(today: Date = new Date()): { total: number; expired: number } {
  return { total: INTEGRATION_OVERRIDES.length, expired: expiredOverrides(today).length };
}
